      font-size: 2.5rem;
      line-height: 1.12;
      letter-spacing: -0.04em;
    }

    .tagline {
      max-width: 62ch;
      margin: 0.9rem 0 0;
      color: var(--muted);
    }

    .header-actions {
      display: flex;
      flex-direction: column;
      align-items: flex-end;
      gap: 1rem;
