    #theme-toggle {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      min-height: 2.75rem;
      padding: 0.55rem 0.9rem;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: var(--card);
      color: var(--text);
      font: inherit;
      font-weight: 650;
      cursor: pointer;
    }

    #theme-toggle:hover {
      border-color: var(--accent);
    }

    .theme-icon {
      font-size: 1.15rem;
      line-height: 1;
    }

    nav {
      display: flex;
      gap: 1.25rem;
      font-weight: 650;
    }

    main {
      padding-block: 2.5rem 3rem;
    }

    section + section {
      margin-top: 4rem;
    }

    h2 {
      margin: 0;
      font-size: 1.75rem;
      line-height: 1.2;
      letter-spacing: -0.025em;
    }

    .section-intro {
      max-width: 68ch;
      margin: 0.75rem 0 1.75rem;
      color: var(--muted);
    }

    .team-note {
      max-width: 68ch;
      margin: 1rem 0 1.75rem;
    }

    .member-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
      gap: 1.5rem;
      align-items: stretch;
    }

    .member-card {
      display: flex;
      flex-direction: column;
      align-items: flex-start;
      padding: 1.5rem;
      border: 1px solid var(--line);
      border-radius: 1rem;
      background: var(--card);
      box-shadow: var(--shadow);
    }

    .member-card img {
      display: block;
      width: 8rem;
      height: 8rem;
      border-radius: 50%;
      object-fit: cover;
      margin-bottom: 1rem;
    }

    h3 {
      margin: 0;
      font-size: 1.25rem;
      line-height: 1.3;
    }

    .study {
      margin: 0.35rem 0 0.85rem;
      color: var(--muted);
      font-size: 0.92rem;
      font-weight: 650;
    }

    .member-card p:not(.study):not(.hot-take) {
      max-width: 70ch;
      margin: 0 0 1rem;
    }

    .hot-take {
      width: 100%;
      margin: auto 0 0;
      padding: 0.65rem 0.8rem;
      border-radius: 0.65rem;
      background: var(--accent);
      color: #FFFFFF;
      font-size: 0.9rem;
      font-weight: 700;
    }

    .future-panel {
      padding: clamp(1.25rem, 4vw, 2.25rem);
      border: 1px solid var(--line);
      border-radius: 1rem;
      background: var(--card);
      box-shadow: var(--shadow);
    }

    .future-panel > p {
      max-width: 68ch;
    }

    .principles {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 1rem;
      margin: 1.5rem 0;
      padding: 0;
      list-style: none;
    }

    .principles li {
      padding: 1rem;
      border: 1px solid var(--line);
      border-radius: 0.75rem;
      background: var(--soft);
    }

    .principles strong {
      display: block;
      margin-bottom: 0.25rem;
    }

    .disagreement {
      margin-top: 1.5rem;
      padding: 1rem 1.2rem;
      border-left: 0.25rem solid var(--accent);
      background: var(--soft);
    }

    .disagreement h3 {
      margin-bottom: 0.5rem;
    }

    .disagreement p {
      margin: 0.5rem 0 0;
      max-width: 68ch;
    }

    .closing-note {
      margin-bottom: 0;
      color: var(--muted);
    }

    footer {
      border-top: 1px solid var(--line);
      color: var(--muted);
      text-align: center;
    }

    .footer-inner {
      padding-block: 1.25rem;
      font-size: 0.8rem;
    }

    .footer-inner p {
      margin: 0;
    }

    @media (max-width: 700px) {
      .header-inner,
      main,
      .footer-inner {
        width: calc(100% - 2rem);
      }

      .header-top {
        flex-direction: column;
        gap: 1.25rem;
      }

      .header-actions {
        align-items: flex-start;
        width: 100%;
      }

      nav {
        flex-wrap: wrap;
      }

      .member-grid {
        grid-template-columns: 1fr;
      }

      .principles {
        grid-template-columns: 1fr;
      }

      main {
        padding-block: 2rem;
      }

      section + section {
        margin-top: 3rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }
  </style>
</head>
<body>
  <header class="site-header">
    <div class="header-inner">
      <div class="header-top">
        <div>
          <p class="eyebrow">Agentic SE Lab · Team introduction</p>
          <h1>The Prompt Engineers Who Can't Center a Div</h1>
          <p class="tagline">Five computer scientists, one recurring CSS mystery, and a shared belief that good engineering still needs humans in the loop.</p>
        </div>
        <div class="header-actions">
          <button id="theme-toggle" type="button" aria-label="Switch to night mode">
            <span class="theme-icon" aria-hidden="true">☾</span>
            <span class="theme-label">Night mode</span>
          </button>
          <nav aria-label="Page navigation">
            <a href="#team">Meet the team</a>
            <a href="#future-of-se">Our shared future</a>
          </nav>
        </div>
      </div>
    </div>
  </header>

  <main>
    <section id="team" aria-labelledby="team-heading">
      <h2 id="team-heading">The team behind the prompts</h2>
      <p class="team-note">We are the Prompt Engineers Who Can't Center a Div: M.Sc. Computer Science students at Paderborn University, comparing notes on agents, software, and the occasional stubborn layout. Our rule of thumb: let AI draft; let humans bring context, taste, and verification.</p>

      <div class="member-grid">
        <article class="member-card">
          <img src="{{image:harsh.jpg}}" alt="Photo of Harsh">
          <h3>Harsh</h3>
          <p class="study">M.Sc. Computer Science, 1st semester; B.E. in Information Technology.</p>
          <p>Harsh studies computer science after earning a B.E. in Information Technology, and spends his time on machine learning and football. His cooking experiments are apparently not always mother-approved; he also has more unfinished ML side projects than finished meals this semester. He finds AI good at explaining code and writing tests, but short on the system context behind them. In five to ten years, he expects developers to direct small teams of agents by splitting work clearly and checking results.</p>
          <p class="hot-take">🔥 Most “AI bugs” are just human requirements that were never written down.</p>
        </article>

        <article class="member-card">
          <img src="{{image:keval.jpg}}" alt="Photo of Keval">
          <h3>Keval</h3>
          <p class="study">M.Sc. Computer Science, 1st semester; B.Tech. in Computer Science.</p>
          <p>Keval is a computer science master's student with a B.Tech. in Computer Science. Cloud and DevOps keep him busy, alongside cricket and long bike rides along the Lippe. His CI pipeline has a better success rate than his alarm clock. Today, he likes AI for scripts, configs, and debugging messages, but watches for insecure shortcuts. Looking five to ten years ahead, he expects agents to deploy, monitor, and repair systems; engineers will need to set careful guardrails, permissions, tests, and rollback plans.</p>
          <p class="hot-take">🔥 Giving an AI agent production access without a sandbox is just chaos engineering with extra steps.</p>
        </article>

        <article class="member-card">
          <img src="{{image:krish.jpg}}" alt="Photo of Krish">
          <h3>Krish</h3>
          <p class="study">M.Sc. Computer Science, 1st semester at Paderborn University.</p>
          <p>Krish studies computer science and builds side projects, follows cricket, and fuels late-night debugging with what may be too much chai. He once fixed a production bug from his phone while waiting in a supermarket queue. For him, AI is useful for boilerplate and first drafts, but someone who understands the system still has to review the work. In five to ten years, he expects engineers to spend less time typing and more time specifying, reviewing, and testing what agents produce. Clear intent will outlast syntax tricks.</p>
          <p class="hot-take">🔥 The best prompt engineer on your team is just the person who writes the clearest tickets.</p>
        </article>

        <article class="member-card">
          <img src="{{image:nevil.jpg}}" alt="Photo of Nevil">
          <h3>Nevil</h3>
          <p class="study">M.Sc. Computer Science, 1st semester; B.E. in Computer Engineering.</p>
          <p>Nevil studies computer science after a B.E. in Computer Engineering, with interests in frontend and UI design, photography, and badminton. He spends more time choosing a colour palette than writing code—which is excellent news for this page. AI can produce a working UI quickly, but he says “working” and “pleasant to use” are not the same thing. In five to ten years, he expects software building to feel more like directing than typing, with user empathy, communication, and design taste doing the heavy lifting.</p>
          <p class="hot-take">🔥 AI can center a div on the first try, which already makes it better than half of us.</p>
        </article>

        <article class="member-card">
          <img src="{{image:nirav.jpg}}" alt="Photo of Nirav">
          <h3>Nirav</h3>
          <p class="study">M.Sc. Computer Science, 1st semester; B.Tech. in Computer Engineering.</p>
          <p>Nirav studies computer science after a B.Tech. in Computer Engineering and enjoys backend systems, table tennis, and sampling every street-food stall in a new place. His laptops all have names borrowed from Bollywood villains. He describes AI as a fast junior developer: tireless and useful for boilerplate, but sometimes too confident, so he reads every line before it reaches main. In five to ten years, he expects code to be the easy part; designing systems, defining correctness, and keeping agents from tripping over one another will be the hard work.</p>
          <p class="hot-take">🔥 An AI that writes 1,000 lines a minute just means 1,000 lines a minute someone has to review.</p>
        </article>
      </div>
    </section>

    <section id="future-of-se" aria-labelledby="future-heading">
      <div class="future-panel">
        <h2 id="future-heading">The Future of Software Engineering</h2>
        <p class="section-intro">Our experience with coding agents so far points to a future where machines can move quickly, but good engineering still depends on people who know what “right” means.</p>

        <ul class="principles">
          <li><strong>Agents are useful teammates.</strong> Let them tackle boilerplate, tests, scripts, configurations, debugging clues, and first drafts.</li>
          <li><strong>Context is the human advantage.</strong> Agents can miss why a system exists, what users need, and which trade-offs matter.</li>
          <li><strong>Clear specifications save time.</strong> Breaking a problem into explicit tasks helps both people and agents do better work.</li>
          <li><strong>Review and verification are core engineering.</strong> Check correctness, usability, security, and operations before trusting the output.</li>
        </ul>

        <div class="disagreement">
          <h3>One friendly disagreement: how much should agents run on their own?</h3>
          <p><strong>More autonomy:</strong> Keval can imagine agents deploying, monitoring, and fixing systems when engineers give them clear permissions, tests, and rollback plans.</p>
          <p><strong>More caution:</strong> Nirav emphasizes defining correctness and reviewing every line, while Harsh stresses that agents still lack the context behind a system’s design.</p>
          <p>Either way, handing an agent a vague task and production access is not a strategy. It is a very fast way to learn what your rollback plan is for.</p>
        </div>

        <p class="closing-note">Our shared prediction: software engineering shifts from writing every line to specifying, directing, reviewing, and verifying the work—and the clearest thinker in the room remains a valuable teammate.</p>
      </div>
    </section>
  </main>

  <footer>
    <div class="footer-inner">
      <p>Built by an agent, supervised by humans. · 2026 · The Prompt Engineers Who Can't Center a Div</p>
    </div>
  </footer>

  <script>
    const themeToggle = document.getElementById("theme-toggle");
    const themeIcon = themeToggle.querySelector(".theme-icon");
    const themeLabel = themeToggle.querySelector(".theme-label");

    function updateThemeControl(theme) {
      const switchTo = theme === "dark" ? "light" : "dark";
      themeToggle.setAttribute("aria-label", `Switch to ${switchTo} mode`);
      themeIcon.textContent = theme === "dark" ? "☀" : "☾";
      themeLabel.textContent = theme === "dark" ? "Day mode" : "Night mode";
    }

    updateThemeControl(document.documentElement.dataset.theme);

    themeToggle.addEventListener("click", () => {
      const nextTheme = document.documentElement.dataset.theme === "dark" ? "light" : "dark";
      document.documentElement.dataset.theme = nextTheme;
      updateThemeControl(nextTheme);
      try {
        localStorage.setItem("upb-theme", nextTheme);
      } catch (_) {
        // The in-page theme still works when storage is unavailable.
      }
    });
  </script>
</body>
</html>
