    var themeToggle = document.getElementById("theme-toggle");
    var themeIcon = themeToggle.querySelector(".theme-icon");
    var themeLabel = themeToggle.querySelector(".theme-label");

    function updateThemeControl(theme) {
      var next = theme === "dark" ? "light" : "dark";
      themeToggle.setAttribute("aria-label", "Switch to " + next + " mode");
      themeIcon.textContent = theme === "dark" ? "☀" : "☾";
      themeLabel.textContent = theme === "dark" ? "Day mode" : "Night mode";
    }

    updateThemeControl(document.documentElement.getAttribute("data-theme"));

    themeToggle.addEventListener("click", function () {
      var current = document.documentElement.getAttribute("data-theme");
      var next = current === "dark" ? "light" : "dark";
      document.documentElement.setAttribute("data-theme", next);
      updateThemeControl(next);
      try {
        localStorage.setItem("upb-theme", next);
      } catch (error) {
        /* Theme switching remains usable if storage is unavailable. */
      }
    });
  </script>
